"""Reproduce finite observation and relative-heat fixtures.
Requires Python 3, sympy and numpy. All original scripts are embedded.
These checks supplement the complete written proofs; they do not evaluate native xi data."""
from pathlib import Path
import json
ROOT=Path(__file__).parent/'check_output_012'
ROOT.mkdir(exist_ok=True)
SCRIPTS=json.loads('{"check_inverse_power_observation.py": "\\"\\"\\"Exact auxiliary algebra checks for IVO; the manuscript proves the inequalities.\\"\\"\\"\\nfrom pathlib import Path\\nimport json\\nimport sympy as s\\ny=s.symbols(\'y\'); z=s.symbols(\'z\'); I=s.I\\ntests=[]\\ndef check(name, truth):\\n    truth=bool(truth)\\n    tests.append({\'name\':name,\'passed\':truth})\\n    if not truth: raise AssertionError(name)\\n\\n# Exact hard-gap scalar allowances.\\nc=s.Rational(1,8192)\\ncheck(\'hard_gap:exponential_base\',16*c*c*10000*81<s.Rational(1,4))\\nfor d in [16,17,32,64,128]:\\n    ratio=s.Rational((1+16*d*d)*(2*d+1)**2,4096*4**d)\\n    check(\'hard_gap:mass_ratio:\'+str(d),ratio<1)\\n    check(\'hard_gap:adjacent_decay:\'+str(d),s.Rational(d+1,d)**4<4)\\n\\n# Normalized Gamma moments, generated with the original monic recurrence.\\nmom=[s.Integer(1)]\\ncoeff=[s.Integer(1)]\\nfor n in range(1,80):\\n    nxt=[s.Integer(0)]*(len(coeff)+1)\\n    for j,v in enumerate(coeff):\\n        nxt[j+1]+=v\\n        if j: nxt[j-1]+=j*(s.Rational(2*j-1,2))*v\\n    coeff=nxt;mom.append(coeff[0])\\nQ=(y*y+s.Rational(1,8192**2))**8\\nqp=s.Poly(s.expand(Q*Q),y)\\ndef moment(j):\\n    return sum(a*mom[i[0]+j] for i,a in qp.terms())\\nwm=[moment(j) for j in range(16)]\\nbeta=s.Rational(16**2,2**27)\\nfor n in range(5):\\n    G=s.Matrix(n+1,n+1,lambda i,j:wm[i+j])\\n    X=s.Matrix(n+1,n+1,lambda i,j:wm[i+j+2])\\n    check(\'weighted_gap:exact_minor:\'+str(n),(X-beta*G).det()>0)\\nfor n in [0,2,4]:\\n    G=s.Matrix(n+1,n+1,lambda i,j:wm[i+j])\\n    e=s.eye(n+1)[:,0]; a=G.inv()*e\\n    H=s.expand(sum(a[j]*y**j for j in range(n+1))/a[0])\\n    check(\'H:anchored:\'+str(n),H.subs(y,0)==1)\\n    for j in range(n+1):\\n        p=s.Poly(s.expand(y*H*y**j),y)\\n        integ=sum(co*wm[ex[0]] for ex,co in p.terms())\\n        check(\'H:odd_orthogonality:\'+str(n)+\':\'+str(j),integ==0)\\n\\n# An actual k=9 upper/lower grid verifies physical shifts and the pole jets.\\nk=9; delta=s.Rational(1,4); gamma=s.Integer(3)\\nupper={(2*b-k)*gamma-I*(2*a-k)*delta for a in range(k+1) for b in range(k+1)}\\nlower=[(2*b-(k-8))*gamma-I*(2*a-(k-8))*delta for a in range(k-7) for b in range(k-7)]\\nindices=[(0,0),(8,8)]\\naa=[s.Integer(1),s.Integer(-1)]\\nzz=[I*((2*r-8)*delta+I*(2*t-8)*gamma) for r,t in indices]\\nfor j,sh in enumerate(zz):\\n    for n,root in enumerate(lower):\\n        check(\'physical_shift:\'+str(j)+\':\'+str(n),s.expand(root-sh) in upper)\\nQl=s.Poly(s.prod(y-v for v in lower).expand(),y)\\nr=2; ds=[s.Integer(2),s.Integer(3)]\\nB=s.Poly(s.prod((y-v)**r for v in zz).expand(),y)\\nnumer=s.Poly(0,y)\\nfor aj,sh in zip(aa,zz):\\n    for n,dn in enumerate(ds,1):\\n        term=s.div(B,s.Poly((y-sh)**n,y))[0]\\n        numer+=aj*dn*term\\np=s.rem(numer*s.invert(B,Ql),Ql)\\nh,rem=s.div(B*p-numer,Ql)\\ncheck(\'pole:full_relation\',rem.is_zero)\\nfor j,(aj,sh) in enumerate(zip(aa,zz)):\\n    Bstar=s.prod((y-v)**r for l,v in enumerate(zz) if l!=j)\\n    f=Ql.as_expr()*h.as_expr()/Bstar\\n    for order in range(r):\\n        val=s.cancel(s.diff(f,y,order).subs(y,sh)/s.factorial(order))\\n        check(\'pole:jet:\'+str(j)+\':\'+str(order),s.simplify(val+aj*ds[r-1-order])==0)\\n\\n# Exact polynomial lift for the actual upper Q at its first cutoff.\\nQu=s.Poly(1,y)\\nfor a in [1,3,5,7,9]:\\n    for b in [1,3,5,7,9]:\\n        u=b*gamma;v=a*delta\\n        Qu*=s.Poly(y**4+2*(v*v-u*u)*y*y+(u*u+v*v)**2,y)\\nA=s.Poly(ds[0]*y+ds[1],y)\\ntr=s.rem(A*s.invert(Qu,s.Poly(y**r,y)),s.Poly(y**r,y))\\nlift,rem=s.div(A-Qu*tr,s.Poly(y**r,y))\\ncheck(\'original_lift:polynomial\',rem.is_zero)\\ncheck(\'original_lift:degree\',lift.degree()<=99)\\ncheck(\'original_lift:quotient\',s.rem(s.Poly(y**r,y)*lift-A,Qu).is_zero)\\ncheck(\'original_lift:all_roots\',Qu.degree()==100 and Qu.eval(0)!=0)\\n\\nout={\'scope\':\'Exact auxiliary fixtures; no native asymptotic or metric evaluation\',\\n     \'passed\':len(tests),\'checks\':tests}\\nPath(__file__).with_name(\'INVERSE_POWER_OBSERVATION_CHECKS.json\').write_text(\\n    json.dumps(out,indent=2),encoding=\'utf-8\')\\nprint(json.dumps({\'passed\':len(tests)}))\\n", "check_inverse_flag_heat.py": "from pathlib import Path\\nimport json\\nimport sympy as s\\nimport numpy as np\\nP=Path(__file__).parent;checks=[]\\ndef ck(name,truth):\\n    if not bool(truth):raise AssertionError(name)\\n    checks.append(name)\\ndef positive(A):\\n    A=A.applyfunc(s.cancel)\\n    return A==A.H and all(A[:i,:i].det()>0 for i in range(1,A.rows+1))\\ndef quotient(H,F):\\n    return (F*H.inv()*F.H).inv().applyfunc(s.cancel)\\nW=s.Matrix([[1,s.I,0],[0,1,s.Rational(1,10**6)],[1,0,1],[0,1,1]])\\nF=s.Matrix([[1,s.I,0],[0,1,2]])\\nH0=W.H*W;Q0=quotient(H0,F)\\nfor j in range(1,5):\\n    # Actual fixed coefficient subquotient; noncommuting full Grams.\\n    Z=s.Matrix([[j,1,s.I,0],[0,1,j,1],[1,0,1,s.I],[0,1,0,1]])\\n    HE=s.eye(4)*3+Z.H*Z\\n    HB=HE-s.eye(4)\\n    hi=s.trace(HE)+1\\n    for tag,H in [(\'E\',HE),(\'B\',HB)]:\\n        HW=W.H*H*W;Q=quotient(HW,F)\\n        L=HW.inv()*F.H*Q\\n        ck(f\'{j}:{tag}:right_inverse\',(F*L-s.eye(2)).applyfunc(s.cancel)==s.zeros(2))\\n        ck(f\'{j}:{tag}:minimum_metric\',(L.H*HW*L-Q).applyfunc(s.cancel)==s.zeros(2))\\n        ck(f\'{j}:{tag}:lower\',positive(Q-Q0))\\n        ck(f\'{j}:{tag}:upper\',positive(hi*Q0-Q))\\n    QE=quotient(W.H*HE*W,F);QB=quotient(W.H*HB*W,F)\\n    ck(f\'{j}:actual_observation_order\',positive(QE-QB))\\n    # Frame transport is kept; its determinant is not discarded at one cutoff.\\n    C=s.Matrix([[2,1],[s.I,3]])\\n    ck(f\'{j}:frame_determinant\',s.simplify((C.H*QE*C).det()-abs(C.det())**2*QE.det())==0)\\n# Finite heat receiver with very small observed mass and non-invariant kernel.\\nM=np.diag([1e-12,1.,2.]);H=M.T@M\\nLambda=np.array([[1e-3,1.,0.],[0.,0.,1.]])\\nQ=np.linalg.inv(Lambda@Lambda.T);L=Lambda.T@Q\\nu=np.array([1.,0.,0.]);v=Lambda@u\\ntheta=float(v@Q@v);Pi=np.outer(v,v@Q)/theta\\ntau=100.;heat=np.diag(np.exp(-tau*np.diag(H)))\\nT=Lambda@heat@L;weight=theta*np.exp(-tau*1e-24)\\neta=1/(1e12-1);r=2*eta/theta+2/theta*np.exp(-tau*(1-1e-24))\\nvals,U=np.linalg.eigh(Q);Qs=(U*np.sqrt(vals))@U.T;Qi=(U*(1/np.sqrt(vals)))@U.T\\ntn=lambda A:np.linalg.svd(Qs@A@Qi,compute_uv=False).sum()\\nck(\'heat:nonzero-small-observed-mass\',0<theta<1.1e-6)\\nck(\'heat:relative-finite-guard\',r<1)\\nck(\'heat:relative-error\',tn(T-weight*Pi)<=weight*r)\\nck(\'heat:normalized-projector\',tn(T/np.trace(T)-Pi)<=2*r/(1-r))\\nAB=Lambda@M@L\\nck(\'heat:kernel-coupling-retained\',np.linalg.norm((np.eye(3)-L@Lambda)@M@L)>1e-5)\\n# The exact Laplace Schur receiver includes its kernel coupling.\\nK=np.array([[1.],[-1e-3],[0.]])\\nK=K/np.linalg.norm(K)\\nOn=L@Qi;X=np.concatenate([K,On],axis=1)\\nHt=X.T@H@X;z=.7\\nsch=z*np.eye(2)+Ht[1:,1:]-Ht[1:,:1]@np.linalg.inv(z*np.eye(1)+Ht[:1,:1])@Ht[:1,1:]\\ndirect=Qs@Lambda@np.linalg.inv(z*np.eye(3)+H)@L@Qi\\nck(\'heat:full-Schur-resolvent\',np.linalg.norm(direct-np.linalg.inv(sch))<1e-12)\\nout={\'status\':\'passed\',\'checks\':len(checks),\'exact_checks\':40,\'floating_heat_checks\':6,\'details\':checks,\\n\'scope\':\'Exact complex nonorthogonal subquotient maps; finite numerical heat example with small observation mass and non-invariant kernel. No native xi data or asymptotic evaluation.\'}\\n(P/\'INVERSE_FLAG_HEAT_CHECKS.json\').write_text(json.dumps(out,indent=2)+\'\\\\n\')\\nprint(json.dumps(out))\\n"}')
for name,source in SCRIPTS.items():
 location=ROOT/name
 location.write_text(source,encoding='utf-8')
 exec(compile(source,str(location),'exec'),{'__name__':'__main__','__file__':str(location)})
